.darma-loader-darma-b7-domino-fall { --accent: var(--loader-color, #7c3aed); width: var(--loader-size, 84px); height: calc(var(--loader-size, 84px) * .5); display: flex; align-items: flex-end; justify-content: space-between; }
.darma-loader-darma-b7-domino-fall span { width: calc(var(--loader-size, 84px) * .1); height: 100%; background: var(--accent); border-radius: calc(var(--loader-size, 84px) * .02); transform-origin: 50% 100%; animation: darma-loader-darma-b7-domino-fall-domino calc(var(--loader-speed, 1s) * 1.6) ease-in-out infinite; }
.darma-loader-darma-b7-domino-fall span:nth-child(1) { animation-delay: 0s; }
.darma-loader-darma-b7-domino-fall span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * .12); }
.darma-loader-darma-b7-domino-fall span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * .24); }
.darma-loader-darma-b7-domino-fall span:nth-child(4) { animation-delay: calc(var(--loader-speed, 1s) * .36); }
.darma-loader-darma-b7-domino-fall span:nth-child(5) { animation-delay: calc(var(--loader-speed, 1s) * .48); }
@keyframes darma-loader-darma-b7-domino-fall-domino { 0% { transform: rotate(0deg); } 30%, 55% { transform: rotate(62deg); } 85%, 100% { transform: rotate(0deg); } }

